// PWM on Arduino pin D3: the switches set the brightness, or SW9 makes it breathe.
module top #(
  parameter CLK_HZ = 50_000_000
) (
  input         MAX10_CLK1_50,
  input  [9:0]  SW,           // SW7-SW0: brightness 0-255; SW9: breathe
  output [15:0] ARDUINO_IO,   // the Arduino header, D0-D15 (D3 is bit 3)
  output [9:0]  LEDR
);
  // Breathing: level climbs to 255 and back, one step every STEP clocks.
  localparam STEP = CLK_HZ / 256;
  reg [31:0] tick  = 0;
  reg [7:0]  level = 0;
  reg        up    = 1'b1;
  always @(posedge MAX10_CLK1_50) begin
    if (tick == STEP - 1) begin
      tick <= 0;
      if (up) begin
        if (level == 8'd255) up <= 1'b0;
        else level <= level + 1;
      end else begin
        if (level == 8'd0) up <= 1'b1;
        else level <= level - 1;
      end
    end else
      tick <= tick + 1;
  end

  // SW9 up: follow the breath; down: the switches.
  wire [7:0] duty = SW[9] ? level : SW[7:0];

  // PWM: high while a free-running 8-bit ramp is below duty.
  reg [7:0] ramp = 0;
  always @(posedge MAX10_CLK1_50) ramp <= ramp + 1;
  wire bright = ramp < duty;

  assign ARDUINO_IO = {12'b0, bright, 3'b000};   // only D3 is driven; the rest stay low
  assign LEDR       = {SW[9], 8'b0, bright};
endmodule

